1	export type Customer = { yearsWithMHPCO: number };
2	
3	export type Scenario = {
4	  customer: Customer;
5	  steps: Step[];
6	};
7	
8	export type Step =
9	  | { op: "quote"; items: Item[] }
10	  | { op: "claim"; policy: number; incident: Incident };
11	
12	export type Item = {
13	  type: string;
14	  material?: string;
15	  enchantment?: number;
16	  cursed?: boolean;
17	};
18	
19	export type Incident = {
20	  cause: string;
21	  damages: Damage[];
22	};
23	
24	export type Damage = {
25	  itemType: string;
26	  amount: number;
27	};
28	
29	export type Result = { premium: number } | { payout: number; remainingCap: number };
30	
31	const PROCESSING_FEE = 5;
32	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
33	
34	// The catalogue of insurable item types. Each type carries both figures the
35	// office needs: what it costs to insure (base premium) and what it is worth
36	// when destroyed (insurance value). Keeping them in one row means a new item
37	// type is one edit, and the two figures can never drift apart.
38	const CATALOGUE: Record<string, { basePremium: number; insuranceValue: number }> = {
39	  sword: { basePremium: 100, insuranceValue: 1000 },
40	  amulet: { basePremium: 60, insuranceValue: 600 },
41	  staff: { basePremium: 80, insuranceValue: 800 },
42	  potion: { basePremium: 40, insuranceValue: 400 },
43	  rune: { basePremium: 25, insuranceValue: 250 },
44	  moonstone: { basePremium: 25, insuranceValue: 250 },
45	};
46	
47	const basePremiumOf = (item: Item): number => CATALOGUE[item.type].basePremium;
48	
49	const BLOCK_SIZE = 3;
50	const BLOCK_BASE_PREMIUM = 60;
51	
52	const formsABuildingBlock = (alikeItems: Item[]): boolean =>
53	  alikeItems.length === BLOCK_SIZE;
54	
55	const sumOfBasePremiums = (items: Item[]): number =>
56	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
57	
58	const CURSE_SURCHARGE_RATE = 0.5;
59	const HIGH_ENCHANTMENT_LEVEL = 5;
60	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
61	
62	const isCursed = (item: Item): boolean => item.cursed === true;
63	
64	const isHighlyEnchanted = (item: Item): boolean =>
65	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
66	
67	// A rate table prices one subject: every row whose risk applies contributes its
68	// rate, and the total is their sum. Both the item surcharges and the policy-wide
69	// modifiers are rate tables — they differ only in what they are applied to.
70	type RateTable<Subject> = { appliesTo: (subject: Subject) => boolean; rate: number }[];
71	
72	const totalRateFrom = <Subject,>(table: RateTable<Subject>, subject: Subject): number =>
73	  table.reduce((total, row) => (row.appliesTo(subject) ? total + row.rate : total), 0);
74	
75	// Every item-specific surcharge is a rate on THAT item's base premium, charged
76	// when its risk applies. Adding a new one means adding a row here — nothing else.
77	const ITEM_SURCHARGES: RateTable<Item> = [
78	  { appliesTo: isCursed, rate: CURSE_SURCHARGE_RATE },
79	  { appliesTo: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
80	];
81	
82	const surchargeRateOn = (item: Item): number => totalRateFrom(ITEM_SURCHARGES, item);
83	
84	const itemSurchargesOn = (items: Item[]): number =>
85	  items.reduce((sum, item) => sum + basePremiumOf(item) * surchargeRateOn(item), 0);
86	
87	// Items of the same type are "alike"; each group is priced together so a
88	// building block can be recognised.
89	const alikeItemGroupsIn = (items: Item[]): Item[][] => [
90	  ...items
91	    .reduce(
92	      (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
93	      new Map<string, Item[]>(),
94	    )
95	    .values(),
96	];
97	
98	const basePremiumOfAlikeItems = (alikeItems: Item[]): number =>
99	  formsABuildingBlock(alikeItems) ? BLOCK_BASE_PREMIUM : sumOfBasePremiums(alikeItems);
100	
101	const policyBaseOf = (items: Item[]): number =>
102	  alikeItemGroupsIn(items).reduce(
103	    (sum, alikeItems) => sum + basePremiumOfAlikeItems(alikeItems),
104	    0,
105	  );
106	
107	// Rounding always favours the MHPCO: premiums up, payouts down.
108	const premiumRoundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
109	
110	const LOYALTY_YEARS = 2;
111	const LOYALTY_DISCOUNT_RATE = -0.2;
112	
113	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = -0.15;
114	
115	// Each item in a quote is treated as a first insurance regardless of customer
116	// history, so this surcharge is unconditional.
117	const appliesUnconditionally = (): boolean => true;
118	
119	const isLongStanding = ({ customer }: QuoteContext): boolean =>
120	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
121	
122	const isFollowUpContract = ({ precedingQuotes }: QuoteContext): boolean =>
123	  precedingQuotes > 0;
124	
125	// A quote is priced from the customer plus its place in the scenario's history.
126	type QuoteContext = { customer: Customer; precedingQuotes: number };
127	
128	// Every policy-wide modifier is a rate on the UNMODIFIED policy base — never on a
129	// base that already includes the item surcharges. Surcharges carry a positive
130	// rate, discounts a negative one. Adding a new one means adding a row here.
131	const POLICY_MODIFIERS: RateTable<QuoteContext> = [
132	  { appliesTo: appliesUnconditionally, rate: FIRST_INSURANCE_SURCHARGE_RATE },
133	  { appliesTo: isLongStanding, rate: LOYALTY_DISCOUNT_RATE },
134	  { appliesTo: isFollowUpContract, rate: FOLLOW_UP_CONTRACT_DISCOUNT_RATE },
135	];
136	
137	const policyModifiersOn = (policyBase: number, context: QuoteContext): number =>
138	  policyBase * totalRateFrom(POLICY_MODIFIERS, context);
139	
140	const quoteFor = (items: Item[], context: QuoteContext): Result => {
141	  const policyBase = policyBaseOf(items);
142	  const riskAdjustedBase = policyBase + itemSurchargesOn(items);
143	  return {
144	    premium: premiumRoundedInMHPCOsFavour(
145	      riskAdjustedBase + policyModifiersOn(policyBase, context) + PROCESSING_FEE,
146	    ),
147	  };
148	};
149	
150	const DEDUCTIBLE_PER_DAMAGE = 100;
151	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
152	
153	const insuranceValueOf = (item: Item): number => CATALOGUE[item.type].insuranceValue;
154	
155	const insuranceSumOf = (items: Item[]): number =>
156	  items.reduce((sum, item) => sum + insuranceValueOf(item), 0);
157	
158	// A policy created by a quote step, tracked by that step's index so later claims
159	// can find it and draw down its cap.
160	type Policy = { items: Item[]; remainingCap: number };
161	
162	const policyFor = (items: Item[]): Policy => ({
163	  items,
164	  remainingCap: insuranceSumOf(items) * CAP_MULTIPLE_OF_INSURANCE_SUM,
165	});
166	
167	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
168	const HALF_REIMBURSEMENT_RATE = 0.5;
169	const FULL_REIMBURSEMENT_RATE = 1;
170	
171	const isHeavilyEnchanted = (item: Item): boolean =>
172	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL;
173	
174	// How much of the damage the MHPCO reimburses, before the deductible bites.
175	const reimbursementRateFor = (item: Item): number =>
176	  isHeavilyEnchanted(item) ? HALF_REIMBURSEMENT_RATE : FULL_REIMBURSEMENT_RATE;
177	
178	const damagedItemIn = (policy: Policy, damage: Damage): Item =>
179	  policy.items.filter((item) => item.type === damage.itemType)[0];
180	
181	const payoutForDamage = (damage: Damage, policy: Policy): number =>
182	  damage.amount * reimbursementRateFor(damagedItemIn(policy, damage)) -
183	  DEDUCTIBLE_PER_DAMAGE;
184	
185	// One incident can damage several items; each damage is settled on its own
186	// (and so bears its own deductible), and the incident pays out their sum.
187	const payoutForIncident = (incident: Incident, policy: Policy): number =>
188	  incident.damages.reduce((sum, damage) => sum + payoutForDamage(damage, policy), 0);
189	
190	// A payout is drawn from the policy's cap, leaving less for later claims.
191	const capDrawnDownBy = (policy: Policy, payout: number): Policy => ({
192	  ...policy,
193	  remainingCap: policy.remainingCap - payout,
194	});
195	
196	const claimFor = (incident: Incident, policy: Policy): [Result, Policy] => {
197	  const payout = payoutForIncident(incident, policy);
198	  const settledPolicy = capDrawnDownBy(policy, payout);
199	  return [{ payout, remainingCap: settledPolicy.remainingCap }, settledPolicy];
200	};
201	
202	// What the scenario has accumulated before the current step: the results so far,
203	// the history a quote is priced against, and the policies earlier quotes created.
204	type ScenarioState = {
205	  results: Result[];
206	  precedingQuotes: number;
207	  policies: Record<number, Policy>;
208	};
209	
210	const INITIAL_SCENARIO_STATE: ScenarioState = {
211	  results: [],
212	  precedingQuotes: 0,
213	  policies: {},
214	};
215	
216	const afterQuote = (
217	  state: ScenarioState,
218	  items: Item[],
219	  customer: Customer,
220	  stepIndex: number,
221	): ScenarioState => ({
222	  results: [
223	    ...state.results,
224	    quoteFor(items, { customer, precedingQuotes: state.precedingQuotes }),
225	  ],
226	  precedingQuotes: state.precedingQuotes + 1,
227	  policies: { ...state.policies, [stepIndex]: policyFor(items) },
228	});
229	
230	const afterClaim = (
231	  state: ScenarioState,
232	  policyIndex: number,
233	  incident: Incident,
234	): ScenarioState => {
235	  const [result, policy] = claimFor(incident, state.policies[policyIndex]);
236	  return {
237	    ...state,
238	    results: [...state.results, result],
239	    policies: { ...state.policies, [policyIndex]: policy },
240	  };
241	};
242	
243	const afterStep = (
244	  state: ScenarioState,
245	  step: Step,
246	  customer: Customer,
247	  stepIndex: number,
248	): ScenarioState =>
249	  step.op === "quote"
250	    ? afterQuote(state, step.items, customer, stepIndex)
251	    : afterClaim(state, step.policy, step.incident);
252	
253	export const runScenario = (scenario: Scenario): { results: Result[] } => {
254	  const { results } = scenario.steps.reduce(
255	    (state, step, stepIndex) => afterStep(state, step, scenario.customer, stepIndex),
256	    INITIAL_SCENARIO_STATE,
257	  );
258	  return { results };
259	};
