317	    const result = runScenario({
318	      customer: { yearsWithMHPCO: 0 },
319	      steps: [
320	        { op: "quote", items: [{ type: "rune" }] },
321	        {
322	          op: "claim",
323	          policy: 0,
324	          incident: { cause: "fire", damages: [{ itemType: "rune", amount: 200 }] },
325	        },
326	      ],
327	    });
328	
329	    // 200 − 100 deductible; cap 2×250 = 500, so 400 remains
330	    expect(result.results[1]).toEqual({ payout: 100, remainingCap: 400 });
